  initBackground() {
    // Starfield (500 stars)
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = [];
    const starSizes = [];
    const starColors = [];

    for (let i = 0; i < 500; i++) {
      const seed = i * 12345 + 67890;
      const x = ((seed * 1103515245) % 1000000) / 1000000 * 20 - 10;
      const y = (((seed * 1103515245) >> 16) % 1000000) / 1000000 * 10 - 5;
      const z = -50 - (i / 500) * 150;

      starPositions.push(x, y, z);
      starSizes.push(1 + (i % 3));

      const depth = i / 500;
      const color = new THREE.Color();
      color.setHSL(0.6 + depth * 0.1, 0.8, 0.5 + depth * 0.3);
      starColors.push(color.r, color.g, color.b);
    }

    starGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('size', new THREE.Float32BufferAttribute(starSizes, 1));
    starGeometry.setAttribute('color', new THREE.Float32BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 0.5,
      vertexColors: true,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending
    });

    this.starfield = new THREE.Points(starGeometry, starMaterial);
    this.scene.add(this.starfield);

    // Planet Horizon (procedural)
    const planetGeometry = new THREE.SphereGeometry(30, 64, 32, 0, Math.PI * 2, 0, Math.PI / 2.5);
    const planetMaterial = new THREE.MeshStandardMaterial({
      color: 0x1a1a3a,
      emissive: 0x0044ff,
      emissiveIntensity: 0.6,
      roughness: 0.8,
      metalness: 0.2
    });

    this.planet = new THREE.Mesh(planetGeometry, planetMaterial);
    this.planet.position.set(0, -15, -40);
    this.scene.add(this.planet);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x404060, 0.3);
    this.scene.add(ambientLight);

    const playerLight = new THREE.PointLight(0x00ffff, 0.5, 20);
    playerLight.position.set(0, 0, 10);
    this.playerLight = playerLight;
    this.scene.add(playerLight);
  }

  startGame() {
    this.state = 'playing';

    // Hide overlays
    if (this.uiElements.menu) this.uiElements.menu.style.display = 'none';
    if (this.uiElements.gameOver) this.uiElements.gameOver.style.display = 'none';
    if (this.uiElements.win) this.uiElements.win.style.display = 'none';

    // Reset game state
    this.score = 0;
    this.lives = 3;
    this.wave = 1;
    this.killsInWave = 0;
    this.totalKills = 0;
    this.comboMultiplier = 1.0;
    this.lastKillTime = performance.now();

    // Reset player
    if (this.player) {
      this.scene.remove(this.player.mesh);
      this.player.dispose();
    }
    this.player = new Player(new THREE.Vector3(0, -8, 0), this.input, this.audio);
    this.motionTrails.addTrail(this.player);

    // Reset aliens
    this.initAliens();

    // Reset projectiles pools
    this.playerBullets.clear();
    this.alienBullets.clear();

    // Reset power-ups
    this.powerUps = [];
    this.activePowerUp = null;
    this.powerUpTimer = 0;

    // Reset boss
    this.boss = null;
    this.isBossWave = false;

    // Update UI
    this.updateUI();

    console.log('Game started');
  }

  initAliens() {
    // Clear existing aliens
    if (this.aliens.length > 0) {
      this.scene.remove(this.alienInstances);
      this.alienInstances.geometry.dispose();
      this.alienInstances.material.dispose();
    }

    this.aliens = [];
    this.alienMatrices = [];
    this.alienTypes = [];
    this.alienHealths = [];
    this.alienDirection = 1;
    this.alienSpeed = 0.3 + (this.wave - 1) * 0.08;

    const rows = 5;
    const cols = 11;
    const startX = -4.5;
    const startY = 2.0;

    // Create instanced mesh for all aliens
    const totalAliens = rows * cols;
    const geometry = new THREE.BufferGeometry();
    const positions = [];
    const colors = [];

    for (let i = 0; i < totalAliens; i++) {
      const row = Math.floor(i / cols);
      const col = i % cols;

      const x = startX + col * 0.8;
      const y = startY - row * 0.6;

      positions.push(x, y, 0);

      // Color based on type (row determines type)
      let color;
      if (row === 0) {
        color = new THREE.Color(0xff0088); // Boss type
      } else if (row < 2) {
        color = new THREE.Color(0x00ffff); // Elite
      } else if (row < 4) {
        color = new THREE.Color(0x00ff00); // Standard
      } else {
        color = new THREE.Color(0xffff00); // Scout
      }

      colors.push(color.r, color.g, color.b);
    }

    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

    const material = new THREE.MeshStandardMaterial({
      vertexColors: true,
      emissive: (row) => row === 0 ? 0xff0088 : (row < 2 ? 0x00ffff : 0x00ff00),
      emissiveIntensity: 0.8,
      roughness: 0.5,
      metalness: 0.3
    });

    this.alienInstances = new THREE.InstancedMesh(geometry, material, totalAliens);
    this.scene.add(this.alienInstances);

    // Initialize individual alien data
    for (let i = 0; i < totalAliens; i++) {
      const row = Math.floor(i / cols);
      const col = i % cols;

      const x = startX + col * 0.8;
      const y = startY - row * 0.6;

      this.aliens.push({
        id: i,
        position: new THREE.Vector3(x, y, 0),
        width: 0.5,
        height: 0.4,
        type: row === 0 ? 'boss' : (row < 2 ? 'elite' : (row < 4 ? 'standard' : 'scout')),
        health: row === 0 ? 10 : (row < 2 ? 3 : 1),
        maxHealth: row === 0 ? 10 : (row < 2 ? 3 : 1),
        alive: true,
        animationFrame: 0
      });

      this.alienTypes.push(this.aliens[i].type);
      this.alienHealths.push(this.aliens[i].health);
    }

    // Update matrices
    this.updateAlienMatrices();
  }

  updateAlienMatrices() {
    const matrix = new THREE.Matrix4();

    for (let i = 0; i < this.aliens.length; i++) {
      if (!this.aliens[i].alive) continue;

      const alien = this.aliens[i];
      matrix.setPosition(alien.position.x, alien.position.y, alien.position.z);
      matrix.scale(new THREE.Vector3(1, 1, 1));

      this.alienInstances.setMatrixAt(i, matrix);
    }

    this.alienInstances.instanceMatrix.needsUpdate = true;
  }

  createPlayerBullet() {
    const bullet = new THREE.Mesh(
      new THREE.BoxGeometry(0.2, 0.8, 0.2),
      new THREE.MeshStandardMaterial({
        color: 0x00ffff,
        emissive: 0x00ffff,
        emissiveIntensity: 1.5,
        roughness: 0.3,
        metalness: 0.7
      })
    );

    bullet.userData = {
      type: 'player',
      velocity: new THREE.Vector3(0, 8.0, 0),
      damage: 1,
      lifetime: 60 // frames
    };

    return bullet;
  }

  createAlienBullet() {
    const bullet = new THREE.Mesh(
      new THREE.BoxGeometry(0.3, 0.4, 0.3),
      new THREE.MeshStandardMaterial({
        color: 0xff0000,
        emissive: 0xff0000,
        emissiveIntensity: 1.2,
        roughness: 0.4,
        metalness: 0.6
      })
    );

    bullet.userData = {
      type: 'alien',
      velocity: new THREE.Vector3(0, -4.0, 0),
      damage: 1,
      lifetime: 120 // frames
    };

    return bullet;
  }

  update(deltaTime) {
    const now = performance.now();
    const hitStopScale = this.hitStop.update(deltaTime);

    if (this.state !== 'playing') {
      this.animateBackground(deltaTime * hitStopScale);
      return;
    }

    // Apply hit-stop to all updates
    const effectiveDelta = deltaTime * hitStopScale;
    this.accumulator += effectiveDelta;

    while (this.accumulator >= this.frameTime) {
      this.updateGameLogic(this.frameTime / 1000);
      this.accumulator -= this.frameTime;
    }

    // Update VFX systems
    this.cameraShake.update(effectiveDelta);
    this.particleManager.update(effectiveDelta);
    this.motionTrails.updateTrails(effectiveDelta);
    this.shockwave.updateShockwaves(effectiveDelta);
    this.floatingText.updateTexts(effectiveDelta);

    // Update power-up timer
    if (this.activePowerUp) {
      this.powerUpTimer -= effectiveDelta;
      if (this.powerUpTimer <= 0) {
        this.deactivatePowerUp();
      }
    }

    // Animate background
    this.animateBackground(effectiveDelta);

    // Update UI
    this.updateUI();
  }

  updateGameLogic(deltaTime) {
    // Player movement and shooting
    if (this.player) {
      this.player.update(deltaTime, this.input);

      // Shooting
      if (this.input.isActionPressed('shoot')) {
        const bullet = this.playerBullets.acquire();
        bullet.position.copy(this.player.mesh.position);
        bullet.userData.lifetime = 60;

        // Power-up modification: spread shot
        if (this.activePowerUp === 'spread') {
          bullet.userData.velocity.x = -2.0;
        } else if (this.activePowerUp === 'rapid' && this.player.canShoot()) {
          const bullet2 = this.playerBullets.acquire();
          bullet2.position.copy(this.player.mesh.position);
          bullet2.userData.velocity.set(2, 8, 0);
          bullet2.userData.lifetime = 60;
        } else if (this.activePowerUp === 'spread') {
          const bullet3 = this.playerBullets.acquire();
          bullet3.position.copy(this.player.mesh.position);
          bullet3.userData.velocity.set(2, 8, 0);
          bullet3.userData.lifetime = 60;
        } else if (this.activePowerUp === 'rapid' && this.player.canShoot()) {
          const bullet2 = this.playerBullets.acquire();
          bullet2.position.copy(this.player.mesh.position);
          bullet2.userData.velocity.set(0, 8, 0);
          bullet2.userData.lifetime = 60;
        }
      }
    }

    // Alien movement
    this.updateAlienMovement(deltaTime);

    // Alien shooting
    this.updateAlienShooting(deltaTime);

    // Update projectiles
    this.updateProjectiles(deltaTime);

    // Update power-ups
    this.updatePowerUps(deltaTime);

    // Check collisions
    this.checkCollisions();

    // Check win/loss conditions
    this.checkGameConditions();
  }

  updateAlienMovement(deltaTime) {
    let hitEdge = false;
    const edgeThreshold = 4.8;

    for (const alien of this.aliens) {
      if (!alien.alive) continue;

      alien.position.x += this.alienDirection * this.alienSpeed * deltaTime * 60;

      // Check edges
      if ((this.alienDirection > 0 && alien.position.x > edgeThreshold) ||
          (this.alienDirection < 0 && alien.position.x < -edgeThreshold)) {
        hitEdge = true;
      }
    }

    // Boss movement (if exists)
    if (this.boss) {
      this.boss.update(deltaTime);
    }

    if (hitEdge) {
      this.alienDirection *= -1;

      for (const alien of this.aliens) {
        if (!alien.alive) continue;

        // Descent with slight random offset
        const descent = 0.3 + Math.random() * 0.2;
        alien.position.y -= descent;

        // Panic mode: increase speed when player health low
        if (this.lives <= 1) {
          this.alienSpeed *= 1.5;
        }
      }

      // Check if aliens reached bottom
      for (const alien of this.aliens) {
        if (!alien.alive) continue;
        if (alien.position.y < -8) {
          this.gameOver();
          return;
        }
      }
    }

    // Update matrices
    this.updateAlienMatrices();
  }

  updateAlienShooting(deltaTime) {
    const aliveAliens = this.aliens.filter(a => a.alive);
    if (aliveAliens.length === 0 || this.isBossWave) return;

    // Panic mode: increased fire rate when player health low
    let fireRate = 0.02; // base chance per frame
    if (this.lives <= 1) {
      fireRate *= 1.5;
    }

    for (const alien of aliveAliens) {
      if (Math.random() < fireRate && this.alienBullets.activeCount < 50) {
        const bullet = this.alienBullets.acquire();
        bullet.position.copy(alien.position);

        // Aim at player with some inaccuracy
        const targetX = this.player.mesh.position.x;
        const spread = (Math.random() - 0.5) * 2;
        bullet.userData.velocity.set(
          (targetX - alien.position.x) * 0.1 + spread,
          -4 - Math.random() * 2,
          0
        );

        bullet.userData.lifetime = 120;
      }
    }
  }

  updateProjectiles(deltaTime) {
    // Player bullets
    for (const bullet of this.playerBullets.activeItems) {
      if (!bullet || !bullet.visible) continue;

      const userData = bullet.userData;
      bullet.position.addScaledVector(userData.velocity, deltaTime);
      userData.lifetime -= deltaTime * 60;

      // Remove if expired or out of bounds
      if (userData.lifetime <= 0 || bullet.position.y > 10) {
        bullet.visible = false;
        this.playerBullets.release(bullet);
      }
    }

    // Alien bullets
    for (const bullet of this.alienBullets.activeItems) {
      if (!bullet || !bullet.visible) continue;

      const userData = bullet.userData;
      bullet.position.addScaledVector(userData.velocity, deltaTime);
      userData.lifetime -= deltaTime * 60;

      // Remove if expired or out of bounds
      if (userData.lifetime <= 0 || bullet.position.y < -10) {
        bullet.visible = false;
        this.alienBullets.release(bullet);
      }
    }
  }

  updatePowerUps(deltaTime) {
    for (let i = this.powerUps.length - 1; i >= 0; i--) {
      const powerUp = this.powerUps[i];

      // Move downward
      powerUp.position.y -= 2.0 * deltaTime;

      // Remove if out of bounds
      if (powerUp.position.y < -10) {
        this.scene.remove(powerUp);
        powerUp.geometry.dispose();
        powerUp.material.dispose();
        this.powerUps.splice(i, 1);
      }
    }
  }

  checkCollisions() {
    // Player bullets vs Aliens
    for (const bullet of this.playerBullets.activeItems) {
      if (!bullet || !bullet.visible) continue;

      const bulletPos = bullet.position;

      for (const alien of this.aliens) {
        if (!alien.alive) continue;

        // AABB collision with padding
        const padding = 0.2;
        if (Math.abs(bulletPos.x - alien.position.x) < (alien.width / 2 + bullet.userData.size?.x || 0.1 + padding) &&
            Math.abs(bulletPos.y - alien.position.y) < (alien.height / 2 + bullet.userData.size?.y || 0.4 + padding)) {

          // Hit!
          alien.health--;
          this.alienHealths[alien.id] = alien.health;

          // Particle burst
          this.particleManager.spawnBurst(bulletPos, 15, new THREE.Color(0xff8800));

          // Shockwave
          this.shockwave.spawnShockwave(bulletPos.clone());

          // Camera shake
          this.cameraShake.applyImpact(3.0);

          // Hit-stop
          this.hitStop.triggerImpact(0.7);

          // Remove bullet
          bullet.visible = false;
          this.playerBullets.release(bullet);

          // Check alien death
          if (alien.health <= 0) {
            this.killAlien(alien);
          }

          break;
        }
      }
    }

    // Alien bullets vs Player
    for (const bullet of this.alienBullets.activeItems) {
      if (!bullet || !bullet.visible) continue;

      const bulletPos = bullet.position;

      if (this.player && Math.abs(bulletPos.x - this.player.mesh.position.x) < 0.5 &&
          Math.abs(bulletPos.y - this.player.mesh.position.y) < 0.5) {

        // Hit player!
        this.hitPlayer();

        // Remove bullet
        bullet.visible = false;
        this.alienBullets.release(bullet);
      }
    }

    // Power-ups vs Player
    if (this.player) {
      for (let i = this.powerUps.length - 1; i >= 0; i--) {
        const powerUp = this.powerUps[i];

        if (Math.abs(powerUp.position.x - this.player.mesh.position.x) < 1.0 &&
            Math.abs(powerUp.position.y - this.player.mesh.position.y) < 1.0) {

          // Collect power-up
          this.collectPowerUp(i);
        }
      }
    }
  }

  killAlien(alien) {
    alien.alive = false;

    // Score calculation based on row/type
    let points = 10;
    if (alien.type === 'scout') points = 10;
    else if (alien.type === 'standard') points = 20;
    else if (alien.type === 'elite') points = 30;
    else if (alien.type === 'boss') points = 50;

    // Combo multiplier
    const now = performance.now();
    if (now - this.lastKillTime < 5000) {
      this.comboMultiplier = Math.min(2.0, this.comboMultiplier + 0.1);
    } else {
      this.comboMultiplier = 1.0;
    }
    this.lastKillTime = now;

    points *= this.comboMultiplier;
    this.score += Math.floor(points);
    this.totalKills++;
    this.killsInWave++;

    // Floating text
    this.floatingText.spawnText(alien.position.clone(), `+${Math.floor(points)}`, Math.floor(points));

    // Explosion particles
    this.particleManager.spawnBurst(alien.position.clone(), 30, new THREE.Color(0xff4400));

    // Shockwave
    this.shockwave.spawnShockwave(alien.position.clone());

    // Camera shake
    this.cameraShake.applyImpact(5.0);

    // Hit-stop
    this.hitStop.triggerImpact(1.0);

    // Audio feedback
    if (this.audio) {
      this.audio.playAlienHit();
    }

    // Chance to drop power-up (3%)
    if (Math.random() < 0.03 && !this.isBossWave) {
      this.spawnPowerUp(alien.position.clone());
    }
  }

  spawnPowerUp(position) {
    const types = ['spread', 'shield', 'rapid'];
    const type = types[Math.floor(Math.random() * types.length)];

    let color;
    if (type === 'spread') color = 0xffff00; // Yellow
    else if (type === 'shield') color = 0x00ffff; // Cyan
    else if (type === 'rapid') color = 0xff00ff; // Magenta

    const geometry = new THREE.RingGeometry(0.3, 0.5, 16);
    const material = new THREE.MeshBasicMaterial({
      color: color,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide
    });

    const powerUp = new THREE.Mesh(geometry, material);
    powerUp.position.copy(position);
    powerUp.userData = { type, rotationSpeed: 2.0 };

    this.scene.add(powerUp);
    this.powerUps.push(powerUp);
  }

  collectPowerUp(index) {
    const powerUp = this.powerUps[index];
    if (!powerUp) return;

    // Remove from scene
    this.scene.remove(powerUp);
    powerUp.geometry.dispose();
    powerUp.material.dispose();
    this.powerUps.splice(index, 1);

    // Apply effect
    const type = powerUp.userData.type;
