    const hitStopScale = this.hitStop.active ? 0.1 : 1.0;

    // Render with composer (post-processing)
    this.composer.render();
  }

  dispose() {
    // Dispose all geometries and materials
    if (this.starfield) {
      this.starfield.geometry.dispose();
      this.starfield.material.dispose();
      this.scene.remove(this.starfield);
    }

    if (this.planet) {
      this.planet.geometry.dispose();
      this.planet.material.dispose();
      this.scene.remove(this.planet);
    }

    if (this.alienInstances) {
      this.alienInstances.geometry.dispose();
      this.alienInstances.material.dispose();
      this.scene.remove(this.alienInstances);
    }

    // Dispose player
    if (this.player) {
      this.player.dispose();
    }

    // Dispose all bullets and power-ups
    for (const bullet of this.playerBullets.activeItems) {
      if (bullet) {
        bullet.geometry.dispose();
        bullet.material.dispose();
      }
    }

    for (const bullet of this.alienBullets.activeItems) {
      if (bullet) {
        bullet.geometry.dispose();
        bullet.material.dispose();
      }
    }

    for (const powerUp of this.powerUps) {
      powerUp.geometry.dispose();
      powerUp.material.dispose();
    }

    // Dispose VFX systems
    this.particleManager.dispose();
    this.motionTrails.dispose();
    this.shockwave.dispose();
    this.floatingText.dispose();

    // Dispose composer and renderer
    this.composer.dispose();
    this.renderer.dispose();

    // Remove event listeners
    window.removeEventListener('resize', () => this.onResize());
    document.removeEventListener('keydown', () => this.onKeyDown());
    document.removeEventListener('keyup', () => this.onKeyUp());
  }
}

// Main entry point for the game
export function initSpaceInvaders(container) {
  const game = new SpaceInvadersGame(container);

  // Game loop
  function animate() {
    requestAnimationFrame(animate);

    const now = performance.now();
    const deltaTime = (now - game.lastTime) / 1000;
    game.lastTime = now;

    game.update(deltaTime);
    game.render();
  }

  animate();

  return game;
}

